import "strings"

func isAnagram(a string, b string) bool {
	bersih := func(s string) string {
		return strings.ReplaceAll(strings.ToLower(s), " ", "")
	}
	hitung := map[rune]int{}
	for _, ch := range bersih(a) {
		hitung[ch]++
	}
	for _, ch := range bersih(b) {
		hitung[ch]--
	}
	for _, n := range hitung {
		if n != 0 {
			return false
		}
	}
	return true
}
